cd /workspace && python3 - <<'EOF'
import urllib.request, re, os
base="http://localhost:8080/"
seen=set(); missing=[]; ok=0
def fetch(url):
    try:
        r=urllib.request.urlopen(url,timeout=5)
        return r.status, r.read().decode('utf-8',errors='replace')
    except urllib.error.HTTPError as e:
        return e.code, ""
    except Exception as e:
        return None, str(e)
start="src/js/controllers/ProfilingController.js"
stack=[start]
while stack:
    rel=stack.pop()
    if rel in seen: continue
    seen.add(rel)
    code,txt=fetch(base+rel)
    if code!=200:
        missing.append((rel,code)); continue
    ok+=1
    d=os.path.dirname(rel)
    for m in re.finditer(r'''(?:from|import)\s+['"]([^'"]+)['"]''',txt):
        imp=m.group(1)
        if imp.startswith('.'):
            np=os.path.normpath(os.path.join(d,imp))
            for c in (np,np+'.js'):
                if c.endswith('.js'): stack.append(c); break
                stack.append(c+'.js'); break
print("modules fetched OK:",ok)
print("missing:",len(missing))
for x in missing[:30]: print(x)
EOF

